def PushNV(N):
    for W in N :
        for C in W :
            if C.upper() in 'AEIOU':
                break
        else:
            NoVowel.append(W)
All=[]
NoVowel=[]

for i in range(5) :
    All.append(input('Enter a Word: '))

PushNV(All)

while NoVowel :
    print(NoVowel.pop(), end=' ')
else :
    print('EmptyStack')

